EXECUTESCRIPTPARA.INTERNALSCRIPTCODE:
#Verfahrensschritte identifizieren und die Schrittnummer in ein bdA schreiben

#Anz Schrittzahl in den Verfahrensparametern ermitteln
AnzVerfschritte=len(Visum.Procedures.Operations.GetAll)

# Nummer relevanter Verfahrensschritte auslesen
for i in range (1,AnzVerfschritte+1):
	code=Visum.Procedures.Operations.ItemByKey(i).AttValue("Code")

	if "NFM_lesen"==code:
		Visum.Net.SetAttValue("C_VFS_NFM_lesen",i)
	if "KGM_schreiben"==code:
		Visum.Net.SetAttValue("C_VFS_KGM_schreiben",i)
	if "KGM_berechnen"==code:
		Visum.Net.SetAttValue("C_VFS_KGM_berechnen",i)
	if "AuswBlock"==code:
		Visum.Net.SetAttValue("C_VFS_AuswBlock",i)
	if "InitAlleKGM"==code:
		Visum.Net.SetAttValue("C_VFS_InitAlleKGM",i)
	if "InitAlleNFM"==code:
		Visum.Net.SetAttValue("C_VFS_InitAlleNFM",i)
	if "InitAlleHM"==code:
		Visum.Net.SetAttValue("C_VFS_InitAlleHM",i)
	if "BlockUmlLW"==code:
		Visum.Net.SetAttValue("C_VFS_BlockUmlLW",i)
	if "BlockUml"==code:
		Visum.Net.SetAttValue("C_VFS_BlockUml",i)
	if "KGMberechnen"==code:
		Visum.Net.SetAttValue("C_VFS_KGMberechnen",i)
	if "ProtSchreiben"==code:
		Visum.Net.SetAttValue("C_VFS_ProtSchreiben",i)

	if "VersSchreiben"==code:
		Visum.Net.SetAttValue("C_VFS_VersSchreiben",i)
	if "UmlPW"==code:
		Visum.Net.SetAttValue("C_VFS_UmlPW",i)
	if "BlockUmlFinal"==code:
		Visum.Net.SetAttValue("C_VFS_BlockUmlFinal",i)
	if "UmlPWFinal"==code:
		Visum.Net.SetAttValue("C_VFS_UmlPWFinal",i)

	if "BlockANB_ERSTELLUNG"==code:
		Visum.Net.SetAttValue("C_BlockANB_ERSTELLUNG",i)

	if "AuswSkript"==code:
		Visum.Net.SetAttValue("C_VFS_AUSWSKRIPT",i)
